-- PostgreSQL/Supabase evolution schema. Not yet applied by the MVP.
create extension if not exists pgcrypto;
create extension if not exists pg_trgm;
create table if not exists sources (id uuid primary key default gen_random_uuid(), name text not null, base_url text not null, license text, access_method text, enabled boolean not null default false, created_at timestamptz not null default now());
create table if not exists retailers (id uuid primary key default gen_random_uuid(), name text not null unique, website text, source_id uuid references sources(id), created_at timestamptz not null default now());
create table if not exists retailer_locations (id uuid primary key default gen_random_uuid(), retailer_id uuid references retailers(id), source_location_id text, name text, city text, postcode text, country_code char(2) not null default 'PL', lat numeric(9,6), lon numeric(9,6), unique(retailer_id,source_location_id));
create table if not exists products (id uuid primary key default gen_random_uuid(), name text not null, normalized_name text not null, brand text, category text, package_quantity numeric, package_unit text, attributes jsonb not null default '{}', created_at timestamptz not null default now());
create index if not exists products_name_trgm on products using gin(normalized_name gin_trgm_ops);
create table if not exists product_categories (id uuid primary key default gen_random_uuid(), parent_id uuid references product_categories(id), name text not null, slug text not null unique);
create table if not exists product_category_links (product_id uuid not null references products(id) on delete cascade, category_id uuid not null references product_categories(id) on delete cascade, primary key(product_id,category_id));
create table if not exists product_identifiers (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, scheme text not null, value text not null, unique(scheme,value));
create table if not exists product_matches (id uuid primary key default gen_random_uuid(), left_product_id uuid references products(id), right_product_id uuid references products(id), match_type text not null check(match_type in ('exact','same-product-different-pack','equivalent','similar','not-comparable')), confidence numeric(4,3) not null check(confidence between 0 and 1), evidence jsonb not null default '{}', checked_at timestamptz not null default now());
create table if not exists price_observations (id uuid primary key default gen_random_uuid(), source_id uuid not null references sources(id), product_id uuid references products(id), retailer_id uuid references retailers(id), location_id uuid references retailer_locations(id), source_record_id text, source_url text not null, amount_grosz bigint not null check(amount_grosz>=0), currency char(3) not null, observed_at timestamptz not null, retrieved_at timestamptz not null default now(), confidence numeric(4,3), status text not null default 'observed', raw jsonb not null default '{}', unique(source_id,source_record_id));
create index if not exists price_product_date on price_observations(product_id,observed_at desc);
create table if not exists promotions (id uuid primary key default gen_random_uuid(), source_id uuid not null references sources(id), product_id uuid references products(id), retailer_id uuid references retailers(id), location_id uuid references retailer_locations(id), source_url text not null, kind text not null, amount_grosz bigint, starts_at date, ends_at date, conditions jsonb not null default '{}', verified_at timestamptz, status text not null default 'unverified');
create table if not exists shopping_lists (id uuid primary key default gen_random_uuid(), owner_id uuid, name text not null default 'Moja lista', created_at timestamptz not null default now());
create table if not exists shopping_list_items (id uuid primary key default gen_random_uuid(), list_id uuid not null references shopping_lists(id) on delete cascade, product_id uuid references products(id), free_text text, quantity numeric not null default 1 check(quantity>0), unit text, sort_order integer not null default 0);
create table if not exists basket_comparisons (id uuid primary key default gen_random_uuid(), list_id uuid references shopping_lists(id), created_at timestamptz not null default now(), max_stores integer, result jsonb not null default '{}');
create table if not exists saved_products (owner_id uuid not null, product_id uuid not null references products(id), target_price_grosz bigint, created_at timestamptz not null default now(), primary key(owner_id,product_id));
create table if not exists user_preferences (owner_id uuid primary key, city text, postcode text, radius_km numeric, preferred_retailers uuid[] not null default '{}', preferences jsonb not null default '{}', updated_at timestamptz not null default now());
create table if not exists ingestion_jobs (id uuid primary key default gen_random_uuid(), source_id uuid not null references sources(id), started_at timestamptz not null default now(), ended_at timestamptz, status text not null, records_seen integer not null default 0, error text);
create table if not exists source_health (source_id uuid primary key references sources(id), checked_at timestamptz not null, status text not null, latency_ms integer, detail jsonb not null default '{}');
-- If Supabase Auth is introduced, enable RLS on all user-owned tables and scope policies to auth.uid().
